def test_deposit_zero_mutant():
    account = BankAccount("Alice")
    try:
        account.deposit(0)
        assert False, "Expected ValueError for deposit zero"
    except ValueError as e:
        assert "deposit must be positive" in str(e)

def test_deposit_negative_mutant():
    account = BankAccount("Bob")
    try:
        account.deposit(-5)
        assert False, "Expected ValueError for deposit negative"
    except ValueError as e:
        assert "deposit must be positive" in str(e)

def test_withdraw_zero_mutant():
    account = BankAccount("Charlie", balance=100)
    try:
        account.withdraw(0)
        assert False, "Expected ValueError for withdraw zero"
    except ValueError as e:
        assert "withdrawal must be positive" in str(e)

def test_withdraw_negative_mutant():
    account = BankAccount("David", balance=200)
    try:
        account.withdraw(-10)
        assert False, "Expected ValueError for withdraw negative"
    except ValueError as e:
        assert "withdrawal must be positive" in str(e)

def test_init_default_balance_mutant():
    account = BankAccount("Eve")
    assert account.balance == 0, "Default balance should be 0"

def test_init_balance_one_mutant():
    account = BankAccount("Frank", balance=1)
    assert account.balance == 1, "Balance should be 1"
